mapper.select:
SELECT id, user_id, checkin_date, raw_text, created_at, updated_at
FROM checkins
WHERE user_id = #{userId}
  AND checkin_date = #{checkinDate}
LIMIT 1

SELECT id, user_id, checkin_date, raw_text, created_at, updated_at
FROM checkins
WHERE user_id = #{userId}
ORDER BY checkin_date DESC
LIMIT #{limit}

mapper.insert:
INSERT INTO checkins (
  id, user_id, checkin_date, raw_text, created_at, updated_at
) VALUES (
  #{id}, #{userId}, #{checkinDate}, #{rawText}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE checkins
SET raw_text = #{rawText},
    updated_at = #{updatedAt}
WHERE id = #{id}
